window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ffe32afd9e80a4af"]={"versions": [{"id": "FIG-ffe32afd9e80a4af", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Schichtendiagramm mit Datenflussdarstellung für den AUTOSAR Classic Platform Communication Stack. Das Diagramm illustriert die vertikale Einbettung des CAN Transport Layers (CanTp) zwischen PDU Router (PduR) und CAN Interface (CanIf) sowie die horizontale, logische Peer-to-Peer-Kommunikation zweier Netzwerkknoten (Sender und Empfänger) über den physischen CAN-Bus nach ISO 15765-2.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten (BSW-Module):</strong></li>\n<li><code>PduR</code> (PDU Router): Obere Schicht; fungiert senderseitig als Quelle und empfängerseitig als Senke für unsegmentierte Nutzdaten.</li>\n<li><code>CanTp</code> (CAN Transport Layer): Vermittlungs- und Segmentierungsschicht; führt Segmentierung, Flow-Control und Reassembly durch.</li>\n<li><code>CanIf</code> (CAN Interface): Untere Schicht zur Abstraktion der CAN-Treiber- und Transceiver-Hardware.</li>\n<li><strong>CAN-Bus:</strong> Physisches Übertragungsmedium, repräsentiert durch die untere durchgehende Buslinie mit gestrichelter Anbindung an <code>CanIf</code>.</li>\n<li><strong>Daten- und Protokolleinheiten:</strong></li>\n<li><code>N-SDU</code> (Network Service Data Unit): Dienstdateneinheit an der oberen Schnittstelle zwischen PduR und CanTp.</li>\n<li><code>N-PCI</code> (Network Protocol Control Information): Protokollsteuerinformation (z. B. Single Frame, First Frame, Consecutive Frame, Flow Control), die CanTp erzeugt bzw. interpretiert.</li>\n<li><code>N-PDU</code> (Network Protocol Data Unit): Vollständige Transport-Protokolldateneinheit, bestehend aus <code>N-PCI</code> und Nutzdaten (<code>N-SDU</code> bzw. Fragment).</li>\n<li><code>L-SDU</code> (Data Link Service Data Unit): Dienstdateneinheit an der Schnittstelle zwischen CanTp und CanIf; entspricht strukturell der <code>N-PDU</code>.</li>\n<li><strong>Schnittstellenbeziehungen:</strong></li>\n<li>Vertikaler Kontroll- und Datenfluss über Schichtengrenzen hinweg (PduR $\\leftrightarrow$ CanTp via N-SDU; CanTp $\\leftrightarrow$ CanIf via L-SDU).</li>\n<li>Horizontale logische Schnittstelle (strichpunktierter Pfeil) für den Austausch der <code>N-PDU</code> zwischen den CanTp-Instanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sendeablauf (linke Säule, Sender):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>PduR</code> übergibt die zu versendende <code>N-SDU</code> an das Modul <code>CanTp</code>.</li>\n<li><code>CanTp</code> kapselt die Nutzdaten mit <code>N-PCI</code> (inkl. Adressierungs- und Fragmentierungsinformationen) und formiert eine oder mehrere <code>N-PDU</code>s.</li>\n<li><code>CanTp</code> reicht jede resultierende <code>N-PDU</code> als <code>L-SDU</code> nach unten an das <code>CanIf</code> weiter.</li>\n<li><code>CanIf</code> steuert die physische Aussendung auf den CAN-Bus über den CAN-Treiber.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Peer-to-Peer-Übertragung (Mitte):</strong></li>\n<li>Die <code>N-PDU</code> wird logisch von der sendenden CanTp-Instanz zur empfangenden CanTp-Instanz übertragen.</li>\n<li><strong>Empfangsablauf (rechte Säule, Empfänger):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom CAN-Bus empfangene Rahmen werden vom <code>CanIf</code> als <code>L-SDU</code> an das <code>CanTp</code> gemeldet und übergeben.</li>\n<li><code>CanTp</code> extrahiert und interpretiert die <code>N-PCI</code>, reassembliert bei Mehrfachrahmen die Teildaten und rekonstruiert die ursprüngliche <code>N-SDU</code>.</li>\n<li><code>CanTp</code> übergibt die vollständige <code>N-SDU</code> an die übergeordnete Schicht <code>PduR</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Identität von PDU und SDU:</strong> Die Abbildung verdeutlicht die normative Äquivalenz <code>N-PDU == L-SDU</code> an der Schichtengrenze zwischen Transport Layer und Data Link Layer; die Protokolldateneinheit des Transportprotokolls bildet direkt die Dienstdateneinheit des CAN-Interfaces.</li>\n<li><strong>Kapselung der Protokollkomplexität:</strong> Weder der PduR noch das CanIf interpretieren die <code>N-PCI</code>. Segmentierungsprotokolle (ISO 15765-2 Single Frame, First Frame, Consecutive Frame, Flow Control) verbleiben strikt intern im <code>CanTp</code>.</li>\n<li><strong>Pufferung & TP-Puffer:</strong> Für segmentierten Transfer müssen Puffer zur Reassembly bzw. Bereitstellung der <code>N-SDU</code> über PduR/CanTp koordiniert werden (z. B. TP-Buffer-Handling, PduR-Cancel-Transmit-Mechanismen).</li>\n<li><strong>Framelängen-Restriktion:</strong> Bei Classic CAN ist die <code>L-SDU</code> (und damit die <code>N-PDU</code>) auf maximal 8 Byte Payload begrenzt, woraus sich bei größeren <code>N-SDU</code>s zwingend die Notwendigkeit der Segmentierung ergibt.</li>\n</ul>"}, {"id": "FIG-b4b81a4e94263061", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Schichtendiagramm mit Datenflussdarstellung für den AUTOSAR Classic Platform Communication Stack. Das Diagramm illustriert die vertikale Einbettung des CAN Transport Layers (CanTp) zwischen PDU Router (PduR) und CAN Interface (CanIf) sowie die horizontale, logische Peer-to-Peer-Kommunikation zweier Netzwerkknoten (Sender und Empfänger) über den physischen CAN-Bus nach ISO 15765-2.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten (BSW-Module):</strong></li>\n<li><code>PduR</code> (PDU Router): Obere Schicht; fungiert senderseitig als Quelle und empfängerseitig als Senke für unsegmentierte Nutzdaten.</li>\n<li><code>CanTp</code> (CAN Transport Layer): Vermittlungs- und Segmentierungsschicht; führt Segmentierung, Flow-Control und Reassembly durch.</li>\n<li><code>CanIf</code> (CAN Interface): Untere Schicht zur Abstraktion der CAN-Treiber- und Transceiver-Hardware.</li>\n<li><strong>CAN-Bus:</strong> Physisches Übertragungsmedium, repräsentiert durch die untere durchgehende Buslinie mit gestrichelter Anbindung an <code>CanIf</code>.</li>\n<li><strong>Daten- und Protokolleinheiten:</strong></li>\n<li><code>N-SDU</code> (Network Service Data Unit): Dienstdateneinheit an der oberen Schnittstelle zwischen PduR und CanTp.</li>\n<li><code>N-PCI</code> (Network Protocol Control Information): Protokollsteuerinformation (z. B. Single Frame, First Frame, Consecutive Frame, Flow Control), die CanTp erzeugt bzw. interpretiert.</li>\n<li><code>N-PDU</code> (Network Protocol Data Unit): Vollständige Transport-Protokolldateneinheit, bestehend aus <code>N-PCI</code> und Nutzdaten (<code>N-SDU</code> bzw. Fragment).</li>\n<li><code>L-SDU</code> (Data Link Service Data Unit): Dienstdateneinheit an der Schnittstelle zwischen CanTp und CanIf; entspricht strukturell der <code>N-PDU</code>.</li>\n<li><strong>Schnittstellenbeziehungen:</strong></li>\n<li>Vertikaler Kontroll- und Datenfluss über Schichtengrenzen hinweg (PduR $\\leftrightarrow$ CanTp via N-SDU; CanTp $\\leftrightarrow$ CanIf via L-SDU).</li>\n<li>Horizontale logische Schnittstelle (strichpunktierter Pfeil) für den Austausch der <code>N-PDU</code> zwischen den CanTp-Instanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sendeablauf (linke Säule, Sender):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>PduR</code> übergibt die zu versendende <code>N-SDU</code> an das Modul <code>CanTp</code>.</li>\n<li><code>CanTp</code> kapselt die Nutzdaten mit <code>N-PCI</code> (inkl. Adressierungs- und Fragmentierungsinformationen) und formiert eine oder mehrere <code>N-PDU</code>s.</li>\n<li><code>CanTp</code> reicht jede resultierende <code>N-PDU</code> als <code>L-SDU</code> nach unten an das <code>CanIf</code> weiter.</li>\n<li><code>CanIf</code> steuert die physische Aussendung auf den CAN-Bus über den CAN-Treiber.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Peer-to-Peer-Übertragung (Mitte):</strong></li>\n<li>Die <code>N-PDU</code> wird logisch von der sendenden CanTp-Instanz zur empfangenden CanTp-Instanz übertragen.</li>\n<li><strong>Empfangsablauf (rechte Säule, Empfänger):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom CAN-Bus empfangene Rahmen werden vom <code>CanIf</code> als <code>L-SDU</code> an das <code>CanTp</code> gemeldet und übergeben.</li>\n<li><code>CanTp</code> extrahiert und interpretiert die <code>N-PCI</code>, reassembliert bei Mehrfachrahmen die Teildaten und rekonstruiert die ursprüngliche <code>N-SDU</code>.</li>\n<li><code>CanTp</code> übergibt die vollständige <code>N-SDU</code> an die übergeordnete Schicht <code>PduR</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Identität von PDU und SDU:</strong> Die Abbildung verdeutlicht die normative Äquivalenz <code>N-PDU == L-SDU</code> an der Schichtengrenze zwischen Transport Layer und Data Link Layer; die Protokolldateneinheit des Transportprotokolls bildet direkt die Dienstdateneinheit des CAN-Interfaces.</li>\n<li><strong>Kapselung der Protokollkomplexität:</strong> Weder der PduR noch das CanIf interpretieren die <code>N-PCI</code>. Segmentierungsprotokolle (ISO 15765-2 Single Frame, First Frame, Consecutive Frame, Flow Control) verbleiben strikt intern im <code>CanTp</code>.</li>\n<li><strong>Pufferung & TP-Puffer:</strong> Für segmentierten Transfer müssen Puffer zur Reassembly bzw. Bereitstellung der <code>N-SDU</code> über PduR/CanTp koordiniert werden (z. B. TP-Buffer-Handling, PduR-Cancel-Transmit-Mechanismen).</li>\n<li><strong>Framelängen-Restriktion:</strong> Bei Classic CAN ist die <code>L-SDU</code> (und damit die <code>N-PDU</code>) auf maximal 8 Byte Payload begrenzt, woraus sich bei größeren <code>N-SDU</code>s zwingend die Notwendigkeit der Segmentierung ergibt.</li>\n</ul>"}], "trans": [{"from": "FIG-ffe32afd9e80a4af", "to": "FIG-b4b81a4e94263061", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
